// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 1, 1000 ether);
        vm.assume(actor != address(c));

        Reverter reverter = new Reverter();

        vm.deal(address(c), amount);

        address owner = c.Owner();
        vm.deal(owner, amount);

        vm.prank(owner);
        bool ok;
        try c.Command{value: amount}(address(reverter), "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
contract Reverter { fallback() external payable { revert(); } }
